loesung.text:
SELECT Kunde_ID, Nachname, Postleitzahl, Ort
FROM Kunde
WHERE Postleitzahl LIKE '_7___';

aufgabe.text:
SELECT RadID, Startzeit, Kilometer FROM Ausleihe
WHERE Zustand = 'laufend' AND Startzeit < DATEADD(DAY, -3, GETDATE())
ORDER BY Startzeit ASC;

